/**
 * Audio latency probe, run inside one browser page.
 *
 * A publisher sends a 1 kHz beep every PERIOD seconds, generated by Web Audio
 * at known AudioContext times. A subscriber in the same page feeds the
 * received track back into the same AudioContext, and an AudioWorklet notes
 * the context time at which each beep arrives. Same clock on both ends, so
 * the difference is exact.
 *
 * What it measures: capture hand-off, Opus encode, network, media server,
 * jitter buffer, decode. What it leaves out: the physical microphone and
 * headphone/speaker latency — identical whichever engine carries the audio.
 */
import { VoiceClient } from '@voxonow/voice-client';
import { Room, RoomEvent, Track, type RemoteTrack } from 'livekit-client';

const PERIOD = 0.5;
const BEEP = 0.05;

export interface ProbeResult {
  engine: string;
  samples: number[];
  missed: number;
  /** Encoder target as negotiated by the sender, if the browser exposes it. */
  sendBitrateKbps?: number;
}

const workletSource = `
class OnsetDetector extends AudioWorkletProcessor {
  constructor() { super(); this.quietFor = 1; }
  process(inputs) {
    const channel = inputs[0] && inputs[0][0];
    if (!channel) return true;
    for (let i = 0; i < channel.length; i++) {
      const loud = Math.abs(channel[i]) > 0.1;
      if (loud && this.quietFor > 0.2 * sampleRate) {
        this.port.postMessage(currentTime + i / sampleRate);
      }
      this.quietFor = loud ? 0 : this.quietFor + 1;
    }
    return true;
  }
}
registerProcessor('onset-detector', OnsetDetector);
`;

async function measure(
  engine: string,
  publish: (track: MediaStreamTrack) => Promise<RTCRtpSender | undefined>,
  received: Promise<MediaStreamTrack>,
  beeps: number,
): Promise<ProbeResult> {
  const ac = new AudioContext({ sampleRate: 48000, latencyHint: 'interactive' });
  await ac.resume();
  await ac.audioWorklet.addModule(URL.createObjectURL(new Blob([workletSource], { type: 'text/javascript' })));

  const oscillator = new OscillatorNode(ac, { frequency: 1000 });
  const gate = new GainNode(ac, { gain: 0 });
  const out = new MediaStreamAudioDestinationNode(ac, { channelCount: 1 });
  oscillator.connect(gate).connect(out);
  oscillator.start();

  const sender = await publish(out.stream.getAudioTracks()[0]!);
  const track = await received;
  // Chrome only feeds a remote WebRTC track into Web Audio while some media
  // element is consuming it.
  const sink = new Audio();
  sink.muted = true;
  sink.srcObject = new MediaStream([track]);
  await sink.play().catch(() => {});
  const detector = new AudioWorkletNode(ac, 'onset-detector');
  ac.createMediaStreamSource(new MediaStream([track])).connect(detector);

  const arrivals: number[] = [];
  detector.port.onmessage = (event) => arrivals.push(event.data as number);

  // Let the path settle (ICE, DTLS, first keyframes, jitter buffer warm-up).
  await new Promise((resolve) => setTimeout(resolve, 2000));

  const start = ac.currentTime + 0.2;
  const emitted: number[] = [];
  for (let i = 0; i < beeps; i++) {
    const t = start + i * PERIOD;
    emitted.push(t);
    gate.gain.setValueAtTime(1, t);
    gate.gain.setValueAtTime(0, t + BEEP);
  }
  await new Promise((resolve) => setTimeout(resolve, (beeps * PERIOD + 1.5) * 1000));

  const samples: number[] = [];
  for (const t of emitted) {
    const arrival = arrivals.find((a) => a > t && a < t + PERIOD);
    if (arrival !== undefined) samples.push(Math.round((arrival - t) * 1000));
  }

  let sendBitrateKbps: number | undefined;
  if (sender) {
    const stats = await sender.getStats();
    stats.forEach((r) => {
      if (r.type === 'outbound-rtp' && r.targetBitrate) sendBitrateKbps = Math.round(r.targetBitrate / 1000);
    });
  }
  oscillator.stop();
  await ac.close();
  return { engine, samples, missed: beeps - samples.length, sendBitrateKbps };
}

/** Our engine: two VoiceClients in one page. */
export async function probeVoxonow(voiceUrl: string, tickets: [string, string], beeps: number): Promise<ProbeResult> {
  const publisher = new VoiceClient({ url: voiceUrl });
  const subscriber = new VoiceClient({ url: voiceUrl });
  const received = new Promise<MediaStreamTrack>((resolve) =>
    subscriber.on('trackSubscribed', (t) => t.kind === 'audio' && resolve(t.track)),
  );
  await subscriber.join(tickets[1]);
  await publisher.join(tickets[0]);
  try {
    return await measure(
      'voxonow (mediasoup)',
      async (track) => {
        await publisher.publish(track, 'microphone');
        return undefined;
      },
      received,
      beeps,
    );
  } finally {
    await publisher.leave();
    await subscriber.leave();
  }
}

/** LiveKit with livekit-client defaults, as Voxonow uses it today. */
export async function probeLiveKit(url: string, tokens: [string, string], beeps: number): Promise<ProbeResult> {
  const publisher = new Room();
  const subscriber = new Room();
  const received = new Promise<MediaStreamTrack>((resolve) =>
    subscriber.on(RoomEvent.TrackSubscribed, (t: RemoteTrack) => t.kind === Track.Kind.Audio && resolve(t.mediaStreamTrack)),
  );
  await subscriber.connect(url, tokens[1]);
  await publisher.connect(url, tokens[0]);
  try {
    return await measure(
      'livekit',
      async (track) => {
        const publication = await publisher.localParticipant.publishTrack(track, { source: Track.Source.Microphone });
        return publication.track?.sender;
      },
      received,
      beeps,
    );
  } finally {
    await publisher.disconnect();
    await subscriber.disconnect();
  }
}

Object.assign(window, { probeVoxonow, probeLiveKit });
